-- File reported-labor-hours vocabulary for curator review, without ratifying it or admitting observations.
-- Eight add_property proposals (one per key, as the schema curator applies one key per proposal) that name the
-- shape of a reported-hours statement: the hours (low, high) and six qualifiers. Cited by prototype row, not by
-- observation: the prototype read forum build posts, auction comments and listing descriptions on 2026-11-20 and
-- no observation exists yet. Approval is a human row in schema_proposal_reviews; nothing here approves, registers a
-- property, writes a review, admits an observation or changes a reader. Pattern:
-- 20261011073134_retained_engine_family_label_proposal.sql. Contract: supabase/sql/test_reported_labor_hours_proposal.sql.
SET statement_timeout = '30s';
SET lock_timeout = '1s';

DO $proposals$
DECLARE
  agent constant text := 'claude-reported-labor-hours';
  pr record;
  v_key text;
BEGIN
  IF encode(sha256(convert_to(pg_get_functiondef('public.fn_schema_proposal_apply(uuid)'::regprocedure), 'UTF8')), 'base64')
      NOT IN ('7qumoyywiZG1GXko/kKEGVr1Yjcn3pAOeBVflP3/1so=', 'tUZdsgAe5iDEAejqpZToqdiZCeAOBZM+HBu9p1Jtmpo=')
      OR public.fn_schema_proposal_required_approvals('add_property') <> 1 THEN
    RAISE EXCEPTION 'Schema curator contract changed; review the proposals';
  END IF;
  FOR pr IN SELECT * FROM (VALUES
    ('3981db96-e02d-4080-a7a0-cb777a03f6bf'::uuid, $payload${"property_key": "labor_hours_reported_low", "label": "Reported labor hours (stated or lower bound)", "data_type": "numeric", "unit": "hour", "namespace_request": "core", "category": "labor", "applies_to_kinds": ["work_record"], "cardinality": "multi", "discriminator_key": "quote_hash", "expected_source_categories": ["auction", "forum", "marketplace", "owner"], "verification_scope": "instance", "description": "Hours of work a person states, in their own words, for one scope of work on this vehicle. The stated figure, or the lower end of a range; for 'over N' or 'at least N' it is N and labor_hours_reported_high is absent. This is the primary key: one observation per statement, one claim per quote, so two different figures for one car stay two claims and are never averaged. It is testimony, not measured time: it does not establish that the hours were paid, itemized or spent on this car, and it is never summed with other tiers. Approximate wording ('about', 'nearly') is kept in the quote, not turned into a range."}$payload$::jsonb,
     $evidence$[{"role": "bounded_discovery", "scope": "One reader, one pass, 2026-11-20, read-only. 396 candidate sentences from forum build posts, auction comments and listing descriptions; 138 real hour statements, 258 rejected with a reason. Not population coverage.", "claims_table_harvest": "evidence_claims work_record rows: 224823; 266 contain an hours figure; 99 of those are assertions; about 27 read as labor statements; 1 is already among the 138."}, {"role": "prototype_row", "source_table": "auction_comments", "row_id": "d65b2a7e-14c3-4b29-815b-d3163a9c7c70", "quote": "approx 400 hours of labor at least", "reads": "low=400, high absent (at least)"}, {"role": "prototype_row", "source_table": "build_posts", "row_id": "0351ed3d-7011-434e-8a7c-f385d31d6ae9", "quote": "Took 255 hours in my shop.", "reads": "low=255, high=255"}, {"role": "prototype_row", "source_table": "vehicles", "row_id": "eef2398b-28b7-4c43-9aee-0f7d69b4ac8c", "quote": "spent nearly 500 hours reassembling and repairing", "reads": "low=500 (approx)"}]$evidence$::jsonb),
    ('3c4d3b7b-217e-4026-804c-ba61ea3ae575'::uuid, $payload${"property_key": "labor_hours_reported_high", "label": "Reported labor hours (upper bound)", "data_type": "numeric", "unit": "hour", "namespace_request": "core", "category": "labor", "applies_to_kinds": ["work_record"], "cardinality": "multi", "discriminator_key": "quote_hash", "expected_source_categories": ["auction", "forum", "marketplace", "owner"], "verification_scope": "instance", "description": "Upper end of a stated range of hours ('1000-1500 hours', '2-3 hrs'), at or above labor_hours_reported_low. Equal to low for a single exact figure. Absent, never defaulted, for an open lower bound ('over 400') or a single approximate figure. Written as the qualifier of one work_record observation whose property_key is labor_hours_reported_low; never an observation of its own. Same structured_data as the primary: quote, quote_hash, source_field."}$payload$::jsonb,
     $evidence$[{"role": "bounded_discovery", "scope": "One reader, one pass, 2026-11-20, read-only. 396 candidate sentences from forum build posts, auction comments and listing descriptions; 138 real hour statements, 258 rejected with a reason. Not population coverage.", "claims_table_harvest": "evidence_claims work_record rows: 224823; 266 contain an hours figure; 99 of those are assertions; about 27 read as labor statements; 1 is already among the 138."}, {"role": "prototype_row", "source_table": "auction_comments", "row_id": "1f5feb9b-963d-4943-b3b4-cb0d01c1d5b3", "quote": "A comprehensive restoration is 1000-1500 hours labor.", "reads": "low=1000, high=1500, kind=estimate"}, {"role": "prototype_row", "source_table": "auction_comments", "row_id": "5649c333-def5-48c9-a816-bd23197ed09f", "quote": "full restorations are 500-1500 hour labor", "reads": "low=500, high=1500, kind=estimate"}, {"role": "prototype_row", "source_table": "build_posts", "row_id": "261dfbf8-1997-47fa-8988-bd4c27767bd1", "quote": "could be accomplished in 2-3hrs taking your time", "reads": "low=2, high=3, scope=task"}]$evidence$::jsonb),
    ('8f649bef-fffa-4212-8bba-31cfe66b23cf'::uuid, $payload${"property_key": "labor_scope", "label": "Reported labor scope", "data_type": "enum", "unit": null, "namespace_request": "core", "category": "labor", "applies_to_kinds": ["work_record"], "cardinality": "multi", "discriminator_key": "quote_hash", "expected_source_categories": ["auction", "forum", "marketplace", "owner"], "verification_scope": "instance", "description": "Allowed values: whole_build (hours for taking the car to a finished state, restoration, rebuild or build total) and task (hours for one job or stage, including body-and-paint of a restoration told alone). Judged from the sentence; a total that excludes named work (paint, engine machining) is still whole_build and the exclusion stays in the quote. A fold keeps the two scopes apart. Written as the qualifier of one work_record observation whose property_key is labor_hours_reported_low; never an observation of its own. Same structured_data as the primary: quote, quote_hash, source_field."}$payload$::jsonb,
     $evidence$[{"role": "bounded_discovery", "scope": "One reader, one pass, 2026-11-20, read-only. 396 candidate sentences from forum build posts, auction comments and listing descriptions; 138 real hour statements, 258 rejected with a reason. Not population coverage.", "claims_table_harvest": "evidence_claims work_record rows: 224823; 266 contain an hours figure; 99 of those are assertions; about 27 read as labor statements; 1 is already among the 138."}, {"role": "prototype_row", "source_table": "auction_comments", "row_id": "94162dd3-cdb4-4371-8fa0-aa34dc1be2b1", "quote": "We have over 1400 hours in this build", "reads": "scope=whole_build"}, {"role": "prototype_row", "source_table": "build_posts", "row_id": "35b64d40-9a32-4d94-a6a5-087eaeed8cc1", "quote": "I did it all in about 6 hours.", "reads": "scope=task, system=suspension"}, {"role": "prototype_row", "source_table": "auction_comments", "row_id": "33930f5e-a15c-43ec-bb2d-ab5cacf6c1ce", "quote": "1650 man hours spent just in body and paint", "reads": "scope=task (one stage of a whole restoration), system=body"}]$evidence$::jsonb),
    ('f1e80fb0-9cbc-43f0-90c5-6736ced4070e'::uuid, $payload${"property_key": "labor_system_key", "label": "Reported labor system", "data_type": "enum", "unit": null, "namespace_request": "core", "category": "labor", "applies_to_kinds": ["work_record"], "cardinality": "multi", "discriminator_key": "quote_hash", "expected_source_categories": ["auction", "forum", "marketplace", "owner"], "verification_scope": "instance", "description": "The car system the hours were spent on, in the system keys public.receipt_line_system and public.vehicle_build_reconstruction already use. Allowed values: engine, machining, fuel, cooling, exhaust, electrical, brakes, steering, suspension, axle, transmission, body, paint, glass, interior, trim, tires, and unplaced for a job that names no one system (teardown, detailing, general). Required for labor_scope=task, absent for whole_build. Not a job code: a finer job key joins labor_operations.code in a later proposal. Written as the qualifier of one work_record observation whose property_key is labor_hours_reported_low; never an observation of its own. Same structured_data as the primary: quote, quote_hash, source_field."}$payload$::jsonb,
     $evidence$[{"role": "bounded_discovery", "scope": "One reader, one pass, 2026-11-20, read-only. 396 candidate sentences from forum build posts, auction comments and listing descriptions; 138 real hour statements, 258 rejected with a reason. Not population coverage.", "claims_table_harvest": "evidence_claims work_record rows: 224823; 266 contain an hours figure; 99 of those are assertions; about 27 read as labor statements; 1 is already among the 138."}, {"role": "prototype_row", "source_table": "build_posts", "row_id": "f9c3fe23-91b1-4024-8534-8a68c17f909f", "quote": "Took about 8 hours total of fab time.", "reads": "system=body, scope=task"}, {"role": "prototype_row", "source_table": "build_posts", "row_id": "9d7b9873-2d05-4d4d-8a21-988708080cdd", "quote": "11 hours total to paint the bed!", "reads": "system=paint"}, {"role": "prototype_row", "source_table": "auction_comments", "row_id": "a8875202-d495-43f0-8f65-cee4d6c069ec", "quote": "3 hours on the air conditioning side just to change header gaskets", "reads": "system=engine, task"}]$evidence$::jsonb),
    ('f104ebc0-306b-4bb9-8945-10e823879b44'::uuid, $payload${"property_key": "labor_time_basis", "label": "Reported labor time basis", "data_type": "enum", "unit": null, "namespace_request": "core", "category": "labor", "applies_to_kinds": ["work_record"], "cardinality": "multi", "discriminator_key": "quote_hash", "expected_source_categories": ["auction", "forum", "marketplace", "owner"], "verification_scope": "instance", "description": "Whose clock the hours are. Allowed values: own (the speaker's or owner's own time), paid_shop (hours a shop spent or billed), book_quote (a published flat-rate or shop-quoted time, not hours actually worked) and unknown when the sentence does not say. Documented paid hours from a receipt or timecard are not this key: they are receipt lines, a higher tier in the supersession order. Written as the qualifier of one work_record observation whose property_key is labor_hours_reported_low; never an observation of its own. Same structured_data as the primary: quote, quote_hash, source_field."}$payload$::jsonb,
     $evidence$[{"role": "bounded_discovery", "scope": "One reader, one pass, 2026-11-20, read-only. 396 candidate sentences from forum build posts, auction comments and listing descriptions; 138 real hour statements, 258 rejected with a reason. Not population coverage.", "claims_table_harvest": "evidence_claims work_record rows: 224823; 266 contain an hours figure; 99 of those are assertions; about 27 read as labor statements; 1 is already among the 138."}, {"role": "prototype_row", "source_table": "build_posts", "row_id": "44055c89-0ec7-49c5-b37b-2f176f930d06", "quote": "2 hours labour later, the hood was still firmly locked", "reads": "time_basis=paid_shop, speaker=owner_seller"}, {"role": "prototype_row", "source_table": "build_posts", "row_id": "b0a02ca9-e9d4-40a2-ac04-42f35ddf37a0", "quote": "Dealerships are billing 3.4 hours labor merely to top off", "reads": "time_basis=book_quote, kind=hearsay"}, {"role": "prototype_row", "source_table": "build_posts", "row_id": "9b19942f-eaf6-4aed-a94c-9a3682fec619", "quote": "Took me about 4 hours to do", "reads": "time_basis=own, speaker=commenter_other_car"}]$evidence$::jsonb),
    ('658df860-28f8-49ee-9d0d-0b7c5a1e4f20'::uuid, $payload${"property_key": "labor_speaker_role", "label": "Reported labor speaker role", "data_type": "enum", "unit": null, "namespace_request": "core", "category": "labor", "applies_to_kinds": ["work_record"], "cardinality": "multi", "discriminator_key": "quote_hash", "expected_source_categories": ["auction", "forum", "marketplace", "owner"], "verification_scope": "instance", "description": "Who made the statement relative to the car the hours are about. Allowed values: owner_seller (the owner or listing seller, about this car), shop_builder (a shop or builder about work it did), commenter_other_car (a commenter about their own different car) and third_party (anyone about this car or a class of car, without having done it). Derived from the source row's author role plus the sentence; it sets how much weight a claim carries and which claims a fold may count for this vehicle. Written as the qualifier of one work_record observation whose property_key is labor_hours_reported_low; never an observation of its own. Same structured_data as the primary: quote, quote_hash, source_field."}$payload$::jsonb,
     $evidence$[{"role": "bounded_discovery", "scope": "One reader, one pass, 2026-11-20, read-only. 396 candidate sentences from forum build posts, auction comments and listing descriptions; 138 real hour statements, 258 rejected with a reason. Not population coverage.", "claims_table_harvest": "evidence_claims work_record rows: 224823; 266 contain an hours figure; 99 of those are assertions; about 27 read as labor statements; 1 is already among the 138."}, {"role": "prototype_row", "source_table": "build_posts", "row_id": "0351ed3d-7011-434e-8a7c-f385d31d6ae9", "quote": "Took 255 hours in my shop.", "reads": "speaker=shop_builder, time_basis=paid_shop"}, {"role": "prototype_row", "source_table": "auction_comments", "row_id": "94162dd3-cdb4-4371-8fa0-aa34dc1be2b1", "quote": "We have over 1400 hours in this build", "reads": "speaker=owner_seller"}, {"role": "prototype_row", "source_table": "build_posts", "row_id": "1a7f0491-eb61-4fbb-8a7e-352418000599", "quote": "took 3 hours to complete", "reads": "speaker=commenter_other_car"}, {"role": "prototype_row", "source_table": "auction_comments", "row_id": "5649c333-def5-48c9-a816-bd23197ed09f", "quote": "full restorations are 500-1500 hour labor", "reads": "speaker=third_party"}]$evidence$::jsonb),
    ('a377fc23-2bdd-4fcd-8ce2-73a07019bbed'::uuid, $payload${"property_key": "labor_stated_subject", "label": "Reported labor stated subject", "data_type": "string", "unit": null, "namespace_request": "core", "category": "labor", "applies_to_kinds": ["work_record"], "cardinality": "multi", "discriminator_key": "quote_hash", "expected_source_categories": ["auction", "forum", "marketplace", "owner"], "verification_scope": "instance", "description": "The year, make and model the sentence names as the subject of the hours, as written ('1970 Pontiac GTO'). Present only when the sentence itself names a vehicle; absent means the observation's own vehicle, which is the thread or listing vehicle and is a soft assumption (a commenter's 'mine' is often another car). A value that differs from the observation's vehicle moves the claim out of that vehicle's baseline. Never decoded or resolved to a vehicles row. Written as the qualifier of one work_record observation whose property_key is labor_hours_reported_low; never an observation of its own. Same structured_data as the primary: quote, quote_hash, source_field."}$payload$::jsonb,
     $evidence$[{"role": "bounded_discovery", "scope": "One reader, one pass, 2026-11-20, read-only. 396 candidate sentences from forum build posts, auction comments and listing descriptions; 138 real hour statements, 258 rejected with a reason. Not population coverage.", "claims_table_harvest": "evidence_claims work_record rows: 224823; 266 contain an hours figure; 99 of those are assertions; about 27 read as labor statements; 1 is already among the 138."}, {"role": "prototype_row", "source_table": "auction_comments", "row_id": "53857788-0d95-48ec-bcc4-e5e70e745da3", "quote": "the last one being a 1970 GTO", "reads": "stated subject names a different car than the listing"}, {"role": "prototype_row", "source_table": "build_posts", "row_id": "41fd1465-2dc1-43cf-af8a-a4e4c8d1136c", "quote": "I spent at least 100 hours on mine.", "reads": "speaker's own other car; model not stated, so no value"}]$evidence$::jsonb),
    ('c6014f3c-de92-4692-bc2d-30f2281f4dfb'::uuid, $payload${"property_key": "labor_statement_kind", "label": "Reported labor statement kind", "data_type": "enum", "unit": null, "namespace_request": "core", "category": "labor", "applies_to_kinds": ["work_record"], "cardinality": "multi", "discriminator_key": "quote_hash", "expected_source_categories": ["auction", "forum", "marketplace", "owner"], "verification_scope": "instance", "description": "What sort of statement it is. Allowed values: actual (the speaker reports hours that were worked), estimate (a rule of thumb or prediction about a class of job, or a future job) and hearsay (a report of someone else's hours). Estimates and hearsay are stored, never mixed into a reported baseline: whether estimates form their own tier is the owner's decision, not this proposal's. Written as the qualifier of one work_record observation whose property_key is labor_hours_reported_low; never an observation of its own. Same structured_data as the primary: quote, quote_hash, source_field."}$payload$::jsonb,
     $evidence$[{"role": "bounded_discovery", "scope": "One reader, one pass, 2026-11-20, read-only. 396 candidate sentences from forum build posts, auction comments and listing descriptions; 138 real hour statements, 258 rejected with a reason. Not population coverage.", "claims_table_harvest": "evidence_claims work_record rows: 224823; 266 contain an hours figure; 99 of those are assertions; about 27 read as labor statements; 1 is already among the 138."}, {"role": "prototype_row", "source_table": "auction_comments", "row_id": "1f5feb9b-963d-4943-b3b4-cb0d01c1d5b3", "quote": "A comprehensive restoration is 1000-1500 hours labor.", "reads": "low=1000, high=1500, kind=estimate"}, {"role": "prototype_row", "source_table": "auction_comments", "row_id": "6c61e4d4-587f-4faa-9e33-a17dcde4e639", "quote": "said he had over 1000", "reads": "kind=hearsay"}, {"role": "prototype_row", "source_table": "auction_comments", "row_id": "f827623a-3ee7-4854-912b-7306c7e484cc", "quote": "870hrs labor, build time?", "reads": "kind=hearsay (a commenter asking)"}, {"role": "prototype_row", "source_table": "build_posts", "row_id": "0351ed3d-7011-434e-8a7c-f385d31d6ae9", "quote": "Took 255 hours in my shop.", "reads": "low=255, high=255"}]$evidence$::jsonb)
  ) AS t(proposal_id, property_payload, proposal_evidence) LOOP
    v_key := pr.property_payload->>'property_key';
    IF EXISTS (SELECT 1 FROM public.observation_properties WHERE property_key = v_key) THEN
      RAISE EXCEPTION 'Reported labor vocabulary already exists (%); inspect its canonical owner', v_key;
    END IF;
    IF EXISTS (SELECT 1 FROM public.schema_proposals WHERE id = pr.proposal_id) THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.schema_proposals
        WHERE id = pr.proposal_id AND proposal_type = 'add_property' AND proposed_by_agent_key = agent
          AND payload = pr.property_payload AND status = 'open' AND promoted_to_id IS NULL
      ) THEN
        RAISE EXCEPTION 'Reported labor proposal changed or resolved (%); preserve curator decision', v_key;
      END IF;
      CONTINUE;
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.schema_proposals
      WHERE proposal_type = 'add_property' AND payload->>'property_key' = v_key
        AND status IN ('open', 'under_review', 'needs_changes', 'approved')
    ) THEN
      RAISE EXCEPTION 'Another proposal owns this vocabulary (%)', v_key;
    END IF;
    INSERT INTO public.schema_proposals (
      id, proposed_by_agent_key, proposal_type, payload, evidence,
      motivating_observation_ids, estimated_scope, backward_compatibility
    ) VALUES (
      pr.proposal_id, agent, 'add_property', pr.property_payload,
      pr.proposal_evidence || jsonb_build_array(
        jsonb_build_object('role', 'harvest_check', 'scope', 'No observation, evidence_claim_values row or registry key carries a reported hours figure today; evidence_claims keeps the sentence only.')),
      ARRAY[]::uuid[],
      '{"initial_consumer":"read-only reported-hours fold, shape in the pull request; nothing reads these keys yet","canonical_consumer":"requires curator approval of all eight keys, a writer change in ingest-observation (imageProperties.ts and the key gate in index.ts) and a reader that lands rows","population_coverage":"unmeasured beyond the prototype cohort","new_paid_inference":false,"replay_changes":false}'::jsonb,
      '{"existing_properties":"unchanged; no existing key names reported labor hours","existing_intake":"labor keys remain refused until the writer is changed","rollback":"Withdraw the still-open proposals. Curator approval is a separate human act.","reviews_written":0,"properties_created":0,"source_observations_written":0}'::jsonb
    );
  END LOOP;
END;
$proposals$;

RESET lock_timeout;
RESET statement_timeout;
